  var TYPES = [["new_ac", "New building needing an accredited checker"], ["landed", "Landed house, 3 storeys or less"], ["aa_minor", "A&A not affecting key structural elements"], ["aa_major", "A&A that strengthens or changes key structural elements"], ["gbw", "Deep excavation or other geotechnical works"], ["single", "Single or 2-storey building within the span limits"]];

