      bca: { pic: "check", n: "16", nl: "tasks the law prescribes for every accredited checker", text: "act with prime regard to public safety and interests", by: "The Professional Engineer's Pledge, Professional Engineers Board Singapore", src: "https://www1.peb.gov.sg/about-us/pe-pledge/" }
