  /* ---------- real cases ---------- */
  window.STCASES = [
    { stage: "Design basis", tag: "2017 · PIE viaduct", img: "img/st-case1.jpg", title: "Five engineers, five different assumptions, nobody checked", when: "14 July 2017", where: "PIE viaduct, Upper Changi",
      story: [["draft", "The QP leads five design engineers with little or no bridge experience. One is on a first bridge."], ["mismatch", "He gives no guidance on the effective width of the corbels. Each engineer uses a different, wrong figure and none is checked."], ["jail", "The corbels could not carry the load even with every safety factor removed. He pleads guilty mid-trial."]],
      big: [["86 weeks", "jail for the design QP, as reported"], ["S$10,000", "fine"], ["1", "worker killed, 10 injured"]],
      lesson: "The QP's signature covers every junior's assumption. Set the design basis in writing and check it before the drawings leave.", grade: "sentence from news reports; no written judgment found",
      src: [["Yahoo News Singapore, 2 Dec 2019", "https://sg.news.yahoo.com/pie-viaduct-collapse-engineer-jailed-86-weeks-fined-10000-070345938.html"], ["Related judgment [2020] SGHC 228", S.j228]] },
    { stage: "Independent check", tag: "2017 · The checker", img: "img/case2.jpg", title: "The checker certified what he never checked", when: "14 July 2017", where: "PIE viaduct, Upper Changi",
      story: [["viaduct", "The accredited checker is appointed to check the viaduct's design independently."], ["falsedoc", "He does no calculation for the permanent corbels, yet certifies that he has. Eight of ten piers are under-designed."], ["jail", "He first claims he did the calculations, then admits he did not. The High Court upholds the sentence."]],
      big: [["6 months", "jail for the accredited checker"], ["8 of 10", "piers inadequately designed"], ["10 to 15", "months the court said was the proper starting range"]],
      lesson: "The checker is personally responsible and cannot delegate. A certificate, a signature and an approval do not cover for one another.",
      src: [["Leong Sow Hon v PP [2020] SGHC 228", S.j228]] },
    { stage: "Ground design", tag: "2004 · Nicoll Highway", img: "img/case5.jpg", title: "The software was right. The model fed into it was wrong", when: "20 April 2004", where: "Circle Line excavation beside Nicoll Highway",
      story: [["deepex", "A 33 m deep excavation in soft marine clay, held by 800 mm walls and ten levels of struts."], ["mismatch", "Soft clay is modelled with the wrong strength parameters, so wall moments are under-predicted by about half. The strut connection is under-designed too."], ["clock", "Walls deflect over 400 mm and stiffeners buckle. Trigger levels are revised upward. The ninth level fails and the system unzips."]],
      big: [["4", "people killed"], ["about 50%", "under-prediction of wall moments"], ["400 mm", "wall deflection before collapse"]],
      lesson: "Know what your software's soil model assumes, and run a hand check. A factor-of-two gap shows on one page.", grade: "technical account from a trade journal reviewing the inquiry",
      src: [["STRUCTURE magazine", S.smag], ["Discussed in [2020] SGHC 228", S.j228]] },
    { stage: "Approval first", tag: "2021 · Balestier Road", img: "img/case4.jpg", title: "\"Submitted\" is not \"approved\"", when: "April to May 2021", where: "453 to 461A Balestier Road",
      story: [["nostamp", "BCA disapproves the footing plans on 8 April. Revised plans are approved on 27 April."], ["crane", "In between, 12 footings are cast to the rejected design. Column bars are bent over and buried to hide it."], ["money", "BCA is tipped off and stops the site. The High Court more than doubles the fines."]],
      big: [["S$140,000", "fine on the builder"], ["S$90,000", "fine on the developer"], ["19 days", "site stopped"]],
      lesson: "Keep a live register of every drawing's approval status, and release nothing to site until the approval letter is in hand.",
      src: [["PP v ZH Builders [2025] SGHC 227", S.j227]] },
    { stage: "Neighbours", tag: "2009 · The Amery", img: "img/st-case5.jpg", title: "The basement was fine. The house next door was not", when: "March to April 2009", where: "Lorong K Telok Kurau",
      story: [["deepex", "A basement car park is excavated for a new condominium."], ["collapse", "The soil under the 1970s house next door moves. The house tilts towards the excavation and keeps tilting for years."], ["gavel", "BCA stops the work. Nine years later the Court of Appeal fixes the cost of putting it right."]],
      big: [["1 in 78", "tilt of the neighbour's house by 2016"], ["S$665,094", "awarded for reinstatement"], ["9 years", "from excavation to final judgment"]],
      lesson: "The impact assessment and tilt limits for neighbours belong on the drawings before the first bucket of soil comes out.",
      src: [["Ng Siok Poh v Sim Lian-Koru Bena JV [2018] SGCA 35", S.amery]],
      also: [["7 charged", "over the 2025 Tanjong Katong sinkhole, including two QPs and the resident engineer. No outcome yet", S.sink]] },
    { stage: "Supervision", tag: "2024 · On site", img: "img/st-case6.jpg", title: "The plans were right. Nobody watched them being built", when: "2023 to 2024", where: "Projects not named by BCA",
      story: [["crane", "Structural works are built differently from the approved structural plans."], ["check", "The supervising QP does not exercise due diligence and does not tell BCA about the deviations."], ["gavel", "BCA prosecutes the QP and, separately, the site supervisors and the builder."]],
      big: [["S$40,000", "fine on a supervising QP"], ["S$16,000", "fine on a site supervisor, or 8 weeks' jail"], ["S$80,000", "fine on a builder for deviating from the plans"]],
      lesson: "Each role is prosecuted separately. Any change on site goes to the design QP first, and critical works are supervised in person.", grade: "BCA lists the name, offence and fine only",
      src: [["BCA enforcement actions, construction projects", S.enf]],
      also: [["3 dead", "when a tower crane collapsed in 2008. Its mast anchors had been certified without being tested", S.crane]] },
    { stage: "Existing buildings", tag: "2026 · Inspection", img: "img/st-case7.jpg", title: "The inspection was signed. It was not carried out", when: "March 2026", where: "Building not named by BCA",
      story: [["check", "A building's periodic structural inspection falls due."], ["falsedoc", "The engineer does not carry it out in the prescribed manner. BCA has found others delegating it entirely and reusing old photographs."], ["gavel", "BCA gives the engineer a conditional warning lasting two years."]],
      big: [["24 months", "conditional warning on the inspecting engineer"], ["30%", "of cladded columns must be exposed"], ["5 or 10", "years between inspections"]],
      lesson: "A periodic inspection is a personal statutory duty with a prescribed method. Walk it yourself, expose what is concealed, and report unauthorised works.", grade: "BCA lists the name, offence and outcome only",
      src: [["BCA enforcement actions", S.enf], ["BCA periodic structural inspection page", S.psipage]] }
  ];

